//! C-interface for the component.
//! This code must be unsafe.
//! Assumptions about correctness are introduced and need to be verified by other means.

use data::*;

#[cfg(test)]
use std::sync::Mutex;

#[cfg(not(test))]
extern "C" {
  fn get_btRecv(value: *mut Common::DummyMessage_Impl) -> bool;
  fn get_btRecv_num_invalid() -> u64;
  fn put_btSend(value: *mut Common::DummyMessage_Impl) -> bool;
}

pub fn unsafe_get_btRecv() -> Option<Common::DummyMessage_Impl>
{
  unsafe {
    let value: *mut Common::DummyMessage_Impl = &mut [0; Common::Common_DummyMessage_Impl_DIM_0];
    if (get_btRecv(value)) {
      return Some(*value);
    } else {
      return None;
    }
  }
}

pub fn unsafe_get_btRecv_num_invalid() -> u64
{
  unsafe {
    return get_btRecv_num_invalid();
  }
}

pub fn unsafe_put_btSend(value: &Common::DummyMessage_Impl) -> bool
{
  unsafe {
    return put_btSend(value as *const Common::DummyMessage_Impl as *mut Common::DummyMessage_Impl);
  }
}

//////////////////////////////////////////////////////////////////////////////////
// Testing Versions
//////////////////////////////////////////////////////////////////////////////////

#[cfg(test)]
lazy_static::lazy_static! {
  // simulate the global C variables that point to the microkit shared memory regions.  In a full
  // microkit system we would be able to mutate the shared memory for out ports since they're r/w,
  // but we couldn't do that for in ports since they are read-only
  pub static ref IN_btRecv: Mutex<Option<Common::DummyMessage_Impl>> = Mutex::new(None);
  pub static ref OUT_btSend: Mutex<Option<Common::DummyMessage_Impl>> = Mutex::new(None);
}

#[cfg(test)]
pub fn initialize_test_globals() {
  unsafe {
    *IN_btRecv.lock().unwrap_or_else(|e| e.into_inner()) = None;
    *OUT_btSend.lock().unwrap_or_else(|e| e.into_inner()) = None;
  }
}

#[cfg(test)]
pub fn get_btRecv(value: *mut Common::DummyMessage_Impl) -> bool
{
  unsafe {
    match *IN_btRecv.lock().unwrap_or_else(|e| e.into_inner()) {
      Some(v) => {
        *value = v;
        return true;
      },
      None => return false,
    }
  }
}

#[cfg(test)]
pub fn get_btRecv_num_invalid() -> u64
{
  return 0;
}

#[cfg(test)]
pub fn put_btSend(value: *mut Common::DummyMessage_Impl) -> bool
{
  unsafe {
    *OUT_btSend.lock().unwrap_or_else(|e| e.into_inner()) = Some(*value);
    return true;
  }
}
